import React, { useEffect, useState } from 'react';
import Navbar from '../components/Navbar';
import Sidebar from '../components/Sidebar';

const FormQuestion = ({
    question,
    numbering,
    handleAnswer,
    handleAddFollowUp,
}) => {
    const [newQuestion, setNewQuestion] = useState('');

    return (
        <div className="border rounded-xl p-5 mb-5 bg-white shadow-sm">

            {/* Question Number */}
            <div className="flex items-center gap-2 mb-3">

                <span className="bg-blue-500 text-white px-3 py-1 rounded-full text-sm">
                    {numbering}
                </span>

                <span className="font-semibold text-gray-700">
                    Question
                </span>

            </div>

            {/* Question Text */}
            <p className="mb-4 text-lg text-gray-800">
                {question.text}
            </p>

            {/* Answer Field */}
            {question.type === 'Short Answer' ? (
                <input
                    type="text"
                    placeholder="Write your answer..."
                    value={question.userAnswer || ''}
                    onChange={(e) =>
                        handleAnswer(question.id, e.target.value)
                    }
                    className="border p-3 rounded-lg w-full focus:outline-none focus:ring-2 focus:ring-blue-400"
                />
            ) : (
                <select
                    value={question.userAnswer || ''}
                    onChange={(e) =>
                        handleAnswer(question.id, e.target.value)
                    }
                    className="border p-3 rounded-lg w-full focus:outline-none focus:ring-2 focus:ring-blue-400"
                >
                    <option value="">Select</option>
                    <option value="True">True</option>
                    <option value="False">False</option>
                </select>
            )}

            {/* Follow Up Question */}
            <div className="mt-5 flex gap-3">

                <input
                    type="text"
                    placeholder="Add follow-up question..."
                    value={newQuestion}
                    onChange={(e) => setNewQuestion(e.target.value)}
                    className="border p-3 rounded-lg flex-1 focus:outline-none focus:ring-2 focus:ring-purple-400"
                />

                <button
                    onClick={() => {
                        if (!newQuestion.trim()) return;

                        handleAddFollowUp(question.id, newQuestion);

                        setNewQuestion('');
                    }}
                    className="bg-purple-500 hover:bg-purple-600 text-white px-5 py-2 rounded-lg transition"
                >
                    Add
                </button>

            </div>

            {/* Child Questions */}
            {question.children?.length > 0 && (
                <div className="ml-8 mt-6 border-l-4 border-blue-300 pl-5">

                    {question.children.map((child, index) => (
                        <FormQuestion
                            key={child.id}
                            question={child}
                            numbering={`${numbering}.${index + 1}`}
                            handleAnswer={handleAnswer}
                            handleAddFollowUp={handleAddFollowUp}
                        />
                    ))}

                </div>
            )}

        </div>
    );
};

const FormPage = () => {
    const [questions, setQuestions] = useState([]);

    useEffect(() => {
        const saved = localStorage.getItem('questions');

        if (saved) {
            setQuestions(JSON.parse(saved));
        }
    }, []);

    // Update User Answer
    const updateAnswer = (id, value, items = questions) => {
        return items.map((item) => {
            if (item.id === id) {
                return {
                    ...item,
                    userAnswer: value,
                };
            }

            return {
                ...item,
                children: updateAnswer(id, value, item.children),
            };
        });
    };

    const handleAnswer = (id, value) => {
        const updated = updateAnswer(id, value);

        setQuestions(updated);

        localStorage.setItem(
            'questions',
            JSON.stringify(updated)
        );
    };

    // Add Follow Up Question
    const addFollowUp = (
        parentId,
        questionText,
        items = questions
    ) => {
        return items.map((item) => {

            if (item.id === parentId) {

                const child = {
                    id: Date.now() + Math.random(),
                    text: questionText,
                    type: 'Short Answer',
                    answer: '',
                    userAnswer: '',
                    children: [],
                };

                return {
                    ...item,
                    children: [...item.children, child],
                };
            }

            return {
                ...item,
                children: addFollowUp(
                    parentId,
                    questionText,
                    item.children
                ),
            };
        });
    };

    const handleAddFollowUp = (
        parentId,
        questionText
    ) => {
        const updated = addFollowUp(
            parentId,
            questionText
        );

        setQuestions(updated);

        localStorage.setItem(
            'questions',
            JSON.stringify(updated)
        );
    };

    return (
        <div className="bg-gradient-to-br from-slate-900 via-slate-800 to-indigo-950 min-h-screen pt-20">

            <Sidebar />

            <div className="flex-1 p-8 overflow-auto">

                <Navbar />

                <div className="bg-white shadow-lg rounded-2xl p-6">

                    <h1 className="text-3xl font-bold text-gray-800 mb-6">
                        User Form
                    </h1>

                    {questions.length === 0 ? (
                        <div className="text-center text-gray-500 py-10">
                            No questions available.
                        </div>
                    ) : (
                        questions.map((question, index) => (
                            <FormQuestion
                                key={question.id}
                                question={question}
                                numbering={`Q${index + 1}`}
                                handleAnswer={handleAnswer}
                                handleAddFollowUp={handleAddFollowUp}
                            />
                        ))
                    )}

                </div>
            </div>
        </div>
    );
};

export default FormPage;
